const SD_ZERO = "#767676";
function sdDivide(D, d) {
  const digits = String(D).split("").map(Number), n = digits.length;
  const steps = [];
  let rem = 0, started = false;
  for (let j = 0; j < n; j++) {
    const cur = rem * 10 + digits[j];
    if (!started && cur < d && j < n - 1) {
      rem = cur;
      continue;
    }
    started = true;
    const q = Math.floor(cur / d);
    steps.push({ j, cur, q, prod: q * d, rem: cur - q * d });
    rem = cur - q * d;
  }
  const atoms = [];
  steps.forEach((s, i) => {
    if (i > 0) atoms.push({ t: "down", j: s.j, s: i });
    atoms.push({ t: "q", s: i });
    if (s.q > 0) {
      atoms.push({ t: "prod", s: i });
      atoms.push({ t: "rem", s: i });
    }
  });
  return { D, d, digits, n, off: 4 - n, steps, atoms, Q: Number(steps.map((s) => s.q).join("")), R: rem };
}
function sdFrame(dv, at, downTo) {
  const col = (j) => dv.off + j;
  const qs = [], rows = [], brought = [];
  const row = (r) => rows[r] || (rows[r] = { r, cells: [], minus: null, rule: null, s: -1 });
  const right = (r, str, c, kind) => str.split("").forEach((ch, i) => row(r).cells.push({ col: c - str.length + 1 + i, ch, kind }));
  let wr = 0, lastJ = -1;
  for (let a = 0; a < Math.min(at, dv.atoms.length); a++) {
    const A = dv.atoms[a], s = dv.steps[A.s];
    if (A.t === "down") {
      row(wr).cells.push({ col: col(A.j), ch: String(dv.digits[A.j]), kind: "down" });
      brought.push({ j: A.j, r: wr });
      lastJ = A.j;
    } else if (A.t === "q") {
      qs.push({ col: col(s.j), ch: String(s.q), zero: s.q === 0, s: A.s });
      lastJ = Math.max(lastJ, s.j);
    } else if (A.t === "prod") {
      const str = String(s.prod), R = row(wr + 1);
      right(wr + 1, str, col(s.j), "prod");
      R.minus = col(s.j) - str.length + 1;
      R.rule = [R.minus, col(s.j)];
      R.s = A.s;
    } else {
      right(wr + 2, String(s.rem), col(s.j), "rem");
      row(wr + 2).s = A.s;
      wr += 2;
    }
  }
  if (wr > 0) for (let j = lastJ + 1; j < Math.min(downTo, dv.n); j++) {
    row(wr).cells.push({ col: col(j), ch: String(dv.digits[j]), kind: "down" });
    brought.push({ j, r: wr });
  }
  return { qs, rows: rows.filter(Boolean), brought, wr, lastJ };
}
